CREATE SCHEMA schema1;
CREATE SCHEMA schema2;
CREATE TABLE schema1.employee (employee_id INT PRIMARY KEY, experience_years INT);
CREATE TABLE schema2.employee (employee_id INT PRIMARY KEY, experience_years INT);
INSERT INTO schema1.employee (employee_id, experience_years) VALUES (1, 5);
INSERT INTO schema2.employee (employee_id, experience_years) VALUES (1, 10);
SELECT schema1.employee.employee_id, ROUND(AVG(schema1.employee.experience_years), 2) AS average_years FROM schema1.employee INNER JOIN schema2.employee ON schema1.employee.employee_id = schema2.employee.employee_id GROUP BY schema1.employee.employee_id;
SELECT schema2.employee.employee_id, ROUND(AVG(schema2.employee.experience_years), 2) AS average_years FROM schema1.employee INNER JOIN schema2.employee ON schema1.employee.employee_id = schema2.employee.employee_id GROUP BY schema2.employee.employee_id;

